    { id: 'conservative', label: 'Conservador' },
] as const satisfies ReadonlyArray<{ id: ScenarioTabId; label: string }>;

function useNotchClipPath(ref: React.RefObject<HTMLDivElement | null>) {
    const [notch, setNotch] = useState<{ d: string; w: number; h: number } | null>(null);

    const update = useCallback(() => {
        const el = ref.current;
        if (!el) return;
        const w = el.offsetWidth;
        const h = el.offsetHeight;
        if (!w || !h) return;

        const r = 24;
        // Notch adapta à largura do container (notebook/tablet) em vez de 400px fixos
        const nw = Math.min(400, Math.max(220, w - 40));
        const nh = w < 900 ? 48 : 54;
        const nr = 13;
        const ir = Math.min(26, Math.floor(nh / 2));
        const nx = (w - nw) / 2;

        const d = [
            `M ${r},0`,
            `L ${nx - nr},0`,
            `Q ${nx},0 ${nx},${nr}`,
            `L ${nx},${nh - ir}`,
            `Q ${nx},${nh} ${nx + ir},${nh}`,
            `L ${nx + nw - ir},${nh}`,
            `Q ${nx + nw},${nh} ${nx + nw},${nh - ir}`,
            `L ${nx + nw},${nr}`,
            `Q ${nx + nw},0 ${nx + nw + nr},0`,
            `L ${w - r},0`,
            `Q ${w},0 ${w},${r}`,
            `L ${w},${h - r}`,
            `Q ${w},${h} ${w - r},${h}`,
            `L ${r},${h}`,
            `Q 0,${h} 0,${h - r}`,
            `L 0,${r}`,
            `Q 0,0 ${r},0 Z`,
        ].join(' ');

        el.style.clipPath = `path("${d}")`;
        setNotch((prev) =>
            prev && prev.d === d && prev.w === w && prev.h === h ? prev : { d, w, h },
        );
    }, [ref]);

    useEffect(() => {
        let ro: ResizeObserver | null = null;
        let raf: number;
        let poll: ReturnType<typeof setInterval> | null = null;

        function setup() {
            const el = ref.current;
            if (!el) return false;
            update();
            ro = new ResizeObserver(update);
            ro.observe(el);
            window.addEventListener('resize', update);
            raf = requestAnimationFrame(update);
            return true;
        }

        // Se o elemento ainda não está no DOM (render condicional),
        // fica em polling de 50ms até que ele apareça.
        if (!setup()) {
            poll = setInterval(() => {
                if (setup()) {
                    clearInterval(poll!);
                    poll = null;
                }
            }, 50);
        }

        return () => {
            if (poll) clearInterval(poll);
            ro?.disconnect();
            window.removeEventListener('resize', update);
            cancelAnimationFrame(raf);
        };
    }, [update, ref]);

    return notch;
}

