import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { useGetScenariosQueryOptions } from '@/hooks/queries/scenarios';
import { useScenariosMutations } from '@/hooks/mutations/use-scenarios-mutations';
import { AuditServices } from '@/services/audit';
import { paginatedTableDisplayMessage } from '@/utils/paginatedTableDisplayMessage';
import { useSuspenseQuery } from '@tanstack/react-query';
import {
    AlertCircle,
    CheckCircle,
    Clock,
    Copy,
    Info,
    MoreVertical,
    Pencil,
    Play,
    Trash2,
    XCircle,
} from 'lucide-react';
import { useEffect, useState } from 'react';
import { TScenariosTableProps } from '../types';
import { QueryKeys } from '@/constants/query-keys';
import queryClient from '@/utils/queryClient';

export function ScenariosTable({
    selectedIds,
    onSelectIds,
    onOpenModal,
    onViewResults,
}: TScenariosTableProps) {
    // ============== #STATE =================
    const [currentPage, setCurrentPage] = useState(1);

    // ============== #MUTATIONS =================
    const { deleteScenarioMutation, runScenarioMutation } = useScenariosMutations();

    // ============== #QUERIES =================
    const { data: scenarios } = useSuspenseQuery({
        ...useGetScenariosQueryOptions(currentPage),
        refetchInterval: (query) => {
            const hasRunning = query.state.data?.results.some(
                (s) => s.last_run_status === 'RUNNING',
            );
            return hasRunning ? 3000 : false;
        },
    });

    useEffect(() => {
        if (scenarios?.next) {
            const nextPage = currentPage + 1;
            queryClient.prefetchQuery({
                queryKey: [QueryKeys.scenarios.list, nextPage],
                queryFn: () => AuditServices.getScenarios(nextPage),
            });
        }
    }, [scenarios, currentPage]);

    // ============== #HANDLERS =================
    function handleChangePage(direction: 'next' | 'previous') {
        if (direction === 'next') {
            setCurrentPage((prev) => prev + 1);
        } else {
            setCurrentPage((prev) => prev - 1);
        }
    }

    const handleSelectAll = (checked: boolean) => {
        if (checked) {
            onSelectIds(scenarios.results.map((s) => s.id));
        } else {
            onSelectIds([]);
        }
    };

    const handleSelectOne = (id: string, checked: boolean) => {
        if (checked) {
            onSelectIds((prev) => [...prev, id]);
        } else {
            onSelectIds((prev) => prev.filter((item) => item !== id));
        }
    };

    const handleRunScenario = (id: string) => {
        runScenarioMutation.mutate(id);
    };

    const handleDeleteScenario = (id: string) => {
        if (!confirm('Tem certeza que deseja excluir este cenário?')) return;
        deleteScenarioMutation.mutate(id);
    };

    return (
        <div className="overflow-x-auto">
            <Table className="min-w-full">
                <TableHeader>
                    <TableRow className="bg-gray-50 dark:bg-meta-4">
                        <TableHead className="w-4 p-4">
                            <Checkbox
                                checked={
                                    selectedIds.length === scenarios.results.length &&
                                    scenarios.results.length > 0
                                }
                                onCheckedChange={(checked) => handleSelectAll(checked as boolean)}
                            />
                        </TableHead>
                        <TableHead>Nome</TableHead>
                        <TableHead className="text-center">Status</TableHead>
                        <TableHead className="text-right">
                            Líquido (Resultante vs Esperado)
                        </TableHead>
                        <TableHead className="text-center">Última Execução</TableHead>
                        <TableHead className="text-center">Ações</TableHead>
                    </TableRow>
                </TableHeader>
                <TableBody className="divide-y divide-stroke dark:divide-strokedark">
                    {scenarios.results.map((s) => (
                        <TableRow
                            key={s.id}
                            className="bg-white transition-colors hover:bg-gray-50 dark:bg-boxdark dark:hover:bg-meta-4"
                        >
                            <TableCell className="w-4 p-4">
                                <Checkbox
                                    checked={selectedIds.includes(s.id)}
                                    onCheckedChange={(checked) =>
                                        handleSelectOne(s.id, checked as boolean)
                                    }
                                />
                            </TableCell>
                            <TableCell className="py-4">
                                <div className="flex flex-col gap-0.5">
                                    <span className="font-semibold text-black dark:text-white">
                                        {s.name}
                                    </span>
                                    {s.description && (
                                        <span
                                            className="max-w-[300px] truncate text-xs text-gray-500 dark:text-gray-400"
                                            title={s.description}
                                        >
                                            {s.description}
                                        </span>
                                    )}
                                </div>
                            </TableCell>
                            <TableCell>
                                <div className="flex items-center justify-center">
                                    {s.last_run_status === 'SUCCESS' && (
                                        <div className="flex items-center rounded-full border border-meta-3/20 bg-meta-3/10 px-3 py-1 text-xs font-medium text-meta-3">
                                            <CheckCircle className="mr-1.5 h-4 w-4" />
                                            Sucesso
                                        </div>
                                    )}
                                    {s.last_run_status === 'RUNNING' && (
                                        <div className="flex animate-pulse items-center rounded-full border border-primary/20 bg-primary/10 px-3 py-1 text-xs font-medium text-primary">
                                            <Clock className="mr-1.5 h-4 w-4" />
                                            Executando
                                        </div>
                                    )}
                                    {s.last_run_status === 'FAILURE' && (
                                        <div className="flex items-center rounded-full border border-meta-1/20 bg-meta-1/10 px-3 py-1 text-xs font-medium text-meta-1">
                                            <AlertCircle className="mr-1.5 h-4 w-4" />
                                            Falha
                                        </div>
                                    )}
                                    {s.last_run_status === 'ERROR' && (
                                        <div className="flex items-center rounded-full border border-meta-8/20 bg-meta-8/10 px-3 py-1 text-xs font-medium text-meta-8">
                                            <XCircle className="mr-1.5 h-4 w-4" />
                                            Erro
                                        </div>
                                    )}
                                    {!s.is_enabled && (
                                        <div className="dark:bg-gray-800 flex items-center rounded-full border border-gray-200 bg-gray-100 px-3 py-1 text-xs font-medium italic text-gray-400 dark:border-gray-700">
                                            Desativado
                                        </div>
                                    )}
                                    {!s.last_run_status && s.is_enabled && (
                                        <div className="dark:bg-gray-800 flex items-center rounded-full border border-gray-200 bg-gray-100 px-3 py-1 text-xs font-medium text-gray-500 dark:border-gray-700">
                                            <Clock className="mr-1.5 h-4 w-4" />
                                            Pendente
                                        </div>
                                    )}
                                </div>
                            </TableCell>
                            <TableCell className="text-right">
                                <div className="flex flex-col items-end gap-0.5">
                                    <div className="flex items-center gap-1.5">
                                        <span
                                            className={`text-xs font-bold ${
                                                s.last_run_status === 'SUCCESS'
                                                    ? 'text-meta-3'
                                                    : s.last_run_status === 'FAILURE'
                                                      ? 'text-meta-1'
                                                      : 'text-gray-400'
                                            }`}
                                        >
                                            {s.last_run_actual_liquido !== null
                                                ? `R$ ${Number(s.last_run_actual_liquido).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`
                                                : '-'}
                                        </span>
                                        <span className="text-[10px] text-gray-400">vs</span>
                                        <span className="font-bold text-black dark:text-white">
                                            R${' '}
                                            {Number(s.expected_liquido).toLocaleString('pt-BR', {
                                                minimumFractionDigits: 2,
                                            })}
                                        </span>
                                    </div>
                                    <span className="text-[10px] font-medium uppercase tracking-widest text-gray-400 dark:text-gray-500">
                                        ± {(Number(s.tolerance_percent) * 100).toFixed(2)}%
                                    </span>
                                </div>
                            </TableCell>
                            <TableCell className="text-center">
                                <div className="text-gray-600 flex flex-col items-center gap-0.5 text-xs dark:text-gray-400">
                                    <span className="font-medium">
                                        {s.last_run_at
                                            ? new Date(s.last_run_at).toLocaleDateString('pt-BR')
                                            : '-'}
                                    </span>
                                    {s.last_run_at && (
                                        <span className="text-[10px] opacity-60">
                                            {new Date(s.last_run_at).toLocaleTimeString('pt-BR', {
                                                hour: '2-digit',
                                                minute: '2-digit',
                                            })}
                                        </span>
                                    )}
                                </div>
                            </TableCell>
                            <TableCell>
                                <div className="flex items-center justify-center gap-1">
                                    <button
                                        onClick={() => onOpenModal(s)}
                                        className="rounded-md p-1.5 text-gray-500 transition-all hover:bg-primary/10 hover:text-primary"
                                        title="Editar"

