'use client';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { COLORS, withAlpha } from '@/design-system';
import { isUserMasterOrDev } from '@/functions/rulesVerification';
import { useBrokerStore } from '@/store/useBroker';
import { useUserInfoStore } from '@/store/userInfo';
import { BrokerUltralightResults } from '@/types/broker';
import { paginatedTableDisplayMessage } from '@/utils/paginatedTableDisplayMessage';
import {
    flexRender,
    getCoreRowModel,
    getFilteredRowModel,
    getPaginationRowModel,
    getSortedRowModel,
    useReactTable
} from '@tanstack/react-table';
import { ChevronDown, ChevronLeft, ChevronRight, ChevronUp, LoaderCircle } from 'lucide-react';
import { useShallow } from 'zustand/react/shallow';
import { useProposalList } from '../../broker/_components/BrokerInfo/ProposalListWrapper';
import { GerencialToolbarButton } from '../_components/shared/GerencialTableAction';
import { GERENCIAL_TABLE_HEAD_ROW_CLASS, GERENCIAL_TABLE_HEAD_TEXT_CLASS } from '../_constants/gerencial-ui';
import { createColumns } from './columns';

export function BrokerPrecatoriosTable() {
    /**
     * ===========>> STORE CONSTS <<==============
     */
    const isCoordenadorOrMaster = useBrokerStore((store) => store.isCoordenadorOrMaster);
    const { userRole } = useUserInfoStore(
        useShallow((s) => ({ userRole: s.data.role, userName: s.data.user, userId: s.data.id })),
    );

    // ===============
    // # Context
    // ===============
    const { proposalListData, isLoading, isError, handleChangePage, currentPage } = useProposalList();

    /**
     * ===========>> TABLE STATES <<==============
     */
    // const [currentPage, setCurrentPage] = useState(1);

    /**
     * ==========>> CONSTS <<==============
     */
    const columns = createColumns(currentPage);
    const filteredColumns = columns.filter((col) => {
        if (col.id === 'usuario' && !isCoordenadorOrMaster && !isUserMasterOrDev(userRole)) {
            return false;
        }

        return true;
    });

    const table = useReactTable({
        data: proposalListData?.results as BrokerUltralightResults[],
        columns: filteredColumns,
        getCoreRowModel: getCoreRowModel(),
        getPaginationRowModel: getPaginationRowModel(),
        getSortedRowModel: getSortedRowModel(),
        getFilteredRowModel: getFilteredRowModel()
    });

    return (
        <>

            <div className="overflow-auto rounded-md border">
                <Table className={GERENCIAL_TABLE_HEAD_ROW_CLASS}>
                    <caption className="sr-only">
                        Lista de propostas de precatórios do broker, com ordenação por coluna e paginação.
                    </caption>
                    <TableHeader className="bg-muted/30">
                        {table.getHeaderGroups().map((headerGroup) => (
                            <TableRow
                                key={headerGroup.id}
                                className="hover:bg-muted/30"
                            >
                                {headerGroup.headers.map((header) => (
                                    <TableHead key={header.id}>
                                        {header.isPlaceholder ? null : (
                                            <div
                                                className={
                                                    header.column.getCanSort()
                                                        ? `flex cursor-pointer select-none items-center gap-1 ${GERENCIAL_TABLE_HEAD_TEXT_CLASS}`
                                                        : GERENCIAL_TABLE_HEAD_TEXT_CLASS
                                                }
                                                {...(header.column.getCanSort()
                                                    ? {
                                                          onClick: header.column.getToggleSortingHandler(),
                                                          role: 'button' as const,
                                                          tabIndex: 0,
                                                          'aria-label': `Ordenar por ${header.column.columnDef.header}`,
                                                          onKeyDown: (e) => {
                                                              if (e.key === 'Enter' || e.key === ' ') {
                                                                  e.preventDefault();
                                                                  header.column.toggleSorting();
                                                              }
                                                          },
                                                      }
                                                    : {})}
                                            >
                                                {flexRender(
                                                    header.column.columnDef.header,
                                                    header.getContext(),
                                                )}
                                                {{
                                                    asc: (
                                                        <ChevronUp
                                                            className="h-4 w-4"
                                                            aria-hidden="true"
                                                        />
                                                    ),
                                                    desc: (
                                                        <ChevronDown
                                                            className="h-4 w-4"
                                                            aria-hidden="true"
                                                        />
                                                    ),
                                                }[header.column.getIsSorted() as string] ?? null}
                                            </div>
                                        )}
                                    </TableHead>
                                ))}
                            </TableRow>
                        ))}
                    </TableHeader>
                    <TableBody>
                        {proposalListData && table.getRowModel().rows?.length ? (
                            table.getRowModel().rows.map((row) => (
                                <TableRow
                                    className="group"
                                    style={
                                        row.original.status === 'Transação Concluída'
                                            ? { background: withAlpha(COLORS.green, 0.08) }
                                            : undefined
                                    }
                                    key={row.id}
                                    data-state={row.getIsSelected() && 'selected'}
                                >
                                    {row.getVisibleCells().map((cell) => (
                                        <TableCell key={cell.id}>
                                            {flexRender(
                                                cell.column.columnDef.cell,
                                                cell.getContext(),
                                            )}
                                        </TableCell>
                                    ))}
                                </TableRow>
                            ))
                        ) : (
                            <TableRow>
                                <TableCell colSpan={8} className="h-24 text-center">
                                    {isLoading && (
                                        <div className="flex animate-fade items-center justify-center gap-2 text-sm text-muted-foreground">
                                            <LoaderCircle
                                                className="h-5 w-5 animate-spin"
                                                style={{ color: COLORS.brand }}
                                                aria-hidden
                                            />
                                            <span>Carregando...</span>
                                        </div>
                                    )}
                                    {!isLoading && (
                                        <span className="animate-fade">
                                            Nenhum registro encontrado
                                        </span>
                                    )}
                                    {isError && (
                                        <span className="animate-fade">
                                            Erro ao carregar os dados. Tente novamente.
                                        </span>
                                    )}
                                </TableCell>
                            </TableRow>
                        )}
                    </TableBody>
                </Table>
            </div>

            {proposalListData && (
                <div className="flex flex-col items-center justify-between space-x-0 space-y-3 py-4 sm:flex-row sm:space-x-2 sm:space-y-0">
                    <div className="flex-1 text-sm text-muted-foreground">
                        {paginatedTableDisplayMessage(currentPage, proposalListData)}
                    </div>
                    <div className="flex items-center space-x-2">
                        <GerencialToolbarButton
                            className="gap-1.5"
                            onClick={() => handleChangePage('previous')}
                            disabled={!proposalListData?.previous}
                            aria-label="Página anterior"
                        >
                            <ChevronLeft className="h-3.5 w-3.5" aria-hidden />
                            Anterior
                        </GerencialToolbarButton>
                        <GerencialToolbarButton
                            className="gap-1.5"
                            onClick={() => handleChangePage('next')}
                            disabled={!proposalListData?.next}
                            aria-label="Próxima página"
                        >
                            Próximo
                            <ChevronRight className="h-3.5 w-3.5" aria-hidden />
                        </GerencialToolbarButton>
                    </div>
                </div>
            )}
        </>
    );
}

