    yellow: { pill: 'bg-amber-500/10 text-amber-700 dark:text-amber-400',       dot: 'bg-amber-400 [box-shadow:0_0_5px_rgba(251,191,36,0.6)]'    },
    blue:   { pill: 'bg-blue-500/10 text-blue-700 dark:text-blue-400',          dot: 'bg-blue-500 [box-shadow:0_0_5px_rgba(59,130,246,0.7)]'     },
    purple: { pill: 'bg-violet-500/10 text-violet-700 dark:text-violet-400',    dot: 'bg-violet-500 [box-shadow:0_0_5px_rgba(139,92,246,0.7)]'   },
    orange: { pill: 'bg-orange-500/10 text-orange-700 dark:text-orange-400',    dot: 'bg-orange-500 [box-shadow:0_0_5px_rgba(249,115,22,0.7)]'   },
    grey:   { pill: 'bg-slate-500/10 text-slate-500 dark:text-slate-400',       dot: 'bg-slate-400'                                              },
};

function BentoDaysInSystemBadge({ dateStr }: { dateStr: string | undefined | null }) {
    const days = countElapsedCalendarDays(dateStr);
    if (days === null) return <span className="text-slate-400 dark:text-slate-500">-</span>;
    const color = days < 20 ? 'green' : days < 60 ? 'yellow' : 'red';
    const { pill } = BADGE_STYLES[color];
    return (
        <span className={cn('inline-flex items-center whitespace-nowrap rounded-full px-2 py-0.5 text-[10px] 4xl:text-[15px] font-medium tabular-nums', pill)}>
            {days} dias
        </span>
    );
}

function BentoStatusBadge({ status }: { status: string | undefined | null }) {
    const color = getPropostaStatusBadgeColor(status);
    const { pill, dot } = BADGE_STYLES[color] ?? BADGE_STYLES.grey;
    return (
        <span className={cn('inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-[10px] 4xl:text-[15px] font-medium', pill)}>
            <span className={cn('size-1.5 shrink-0 rounded-full', dot)} />
            <span className="bento-status-badge-label max-w-[100px] truncate">{status ?? 'Sem status'}</span>
        </span>
    );
}

const PIP_STYLES: Record<StatusTone, string> = {
    success: 'bg-emerald-500 [box-shadow:0_0_6px_rgba(16,185,129,0.7)]',
    warning: 'bg-amber-400 [box-shadow:0_0_6px_rgba(251,191,36,0.55)]',
    danger:  'bg-rose-500 [box-shadow:0_0_6px_rgba(244,63,94,0.7)]',
    neutral: 'bg-slate-400',
};

function BentoCompletionPip({ isComplete }: { isComplete: boolean | undefined | null }) {
    const { tone, label } = getStatusIndicator(isComplete);
    return (
        <span title={label} className={cn('inline-block size-3 rounded-full', PIP_STYLES[tone])} />
    );
}

// --- Meus Precatórios columns ---
const collapsedColumns: ColumnDef<BrokerUltralightResults>[] = [
