const expandedColumns: ColumnDef<BrokerUltralightResults>[] = [
    ...collapsedColumns.slice(0, 2),
    {
        id: 'proposal',
        header: 'Proposta',
        cell: ({ row }) => (
            <span className="whitespace-nowrap tabular-nums text-slate-600 dark:text-slate-300">
                {formatMoney(row.original.proposta)}
            </span>
