            </span>
        ),
    },
    {
        id: 'comissao',
        header: 'Comissão',
        cell: ({ row }) => (
            <span className="whitespace-nowrap font-medium tabular-nums text-emerald-600 dark:text-emerald-400">
                {formatMoney(row.original.comissao_rede)}
            </span>
        ),
    },
];

const networkExpandedColumns: ColumnDef<NetworkProposalData>[] = [
    networkCollapsedColumns[0],
    networkCollapsedColumns[1],
    {
        id: 'netValue',
        header: 'Valor Líquido',
        cell: ({ row }) => (
            <span className="whitespace-nowrap tabular-nums text-slate-600 dark:text-slate-300">
                {formatMoney(row.original.valor_liquido)}
            </span>
