    },
    {
        id: 'documents',
        header: 'Documentos',
        cell: ({ row }) => <BentoCompletionPip isComplete={row.original.documentos?.is_complete} />,
    },
    {
        id: 'status',
        header: 'Status',
        cell: ({ row }) => <BentoStatusBadge status={row.original.status_label} />,
    },
];

export type TableTabId = 'meus' | 'rede';

interface PrecatoriosTableBentoCardProps {
    isExpanded: boolean;
    activeTab: TableTabId;
}

export function PrecatoriosTableBentoCard({ isExpanded, activeTab }: PrecatoriosTableBentoCardProps) {

