import { ErrorMessageBox } from "@/components/ErrorMessage/ErrorMessageBox";
import { Button } from "@/components/ui/button";
import { Carousel, CarouselApi, CarouselContent, CarouselItem } from "@/components/ui/carousel";
import { paginatedTableDisplayMessage } from "@/utils/paginatedTableDisplayMessage";
import { useEffect, useState } from "react";
import { useProposalList } from "../ProposalListWrapper";
import { BrokerProposalListCard } from "./BrokerProposalListCard";

export function BrokerProposalList({ isFromGerencial = false }: { isFromGerencial?: boolean }) {
    const {
        proposalListData,
        isLoading,
        isError,
        isRefetching,
        refetch,
        currentPage,
        handleChangePage,
    } = useProposalList();

    const [api, setApi] = useState<CarouselApi>();
    const [current, setCurrent] = useState(0);
    const [count, setCount] = useState(0);

    useEffect(() => {
        if (!api) return;

        // Função para atualizar os estados de contagem e posição atual
        const onSelect = () => {
            setCurrent(api.selectedScrollSnap());
        };

        const onInit = () => {
            setCount(api.scrollSnapList().length);
            setCurrent(api.selectedScrollSnap());
            api.scrollTo(0, true);
        };

        // Dispara inicialmente e quando o carrossel for re-inicializado (ex: dados mudaram)
        onInit();

        api.on("select", onSelect);
        api.on("reInit", onInit); // Importante para quando os itens mudam

        return () => {
            api.off("select", onSelect);
            api.off("reInit", onInit);
        };
    }, [api, proposalListData]);

    if (isLoading) return (
        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3].map((i) => (
                <div key={i} className="h-[400px] w-full animate-pulse rounded-lg bg-slate-100 dark:bg-slate-800" />
            ))}
        </div>
    );

    if (isError) return (
        <ErrorMessageBox
            className="border-0 shadow-none"
            retryFn={refetch}
            isRetrying={isRefetching}
        />
    );

    if (!proposalListData?.results.length) return (
        <div className="flex mb-5 h-24 items-center justify-center rounded-lg border border-dashed border-border bg-boxdark-2">
            <span className="text-sm text-muted-foreground">Nenhum registro encontrado</span>
        </div>
    );

    return (
        <div className="space-y-6">
            <Carousel
                opts={{
                    align: 'start',
                }}
                setApi={setApi}
            >
                <CarouselContent className="pb-2">
                    {proposalListData.results.map((proposal) => (
                        <CarouselItem key={proposal.uuid} className="basis-full pl-4 sm:basis-1/2">
                            <BrokerProposalListCard
                                isFromGerencial={isFromGerencial}
                                proposal={proposal}
                            />
                        </CarouselItem>
                    ))}
                </CarouselContent>
                <div className="py-2 text-center flex justify-center gap-2">
                    {Array.from({ length: count }).map((_, i) => (
                        <button
                            key={i}
                            className={`h-2 w-2 rounded-full transition-all ${i === current ? "bg-blue-600 w-4" : "bg-muted"
                                }`}
                            onClick={() => api?.scrollTo(i)}
                        />
                    ))}
                </div>
            </Carousel>

            {/* <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
                {proposalListData.results.map((proposal) => (
                    <BrokerProposalListCard key={proposal.uuid} proposal={proposal} />
                ))}
            </div> */}

            <div className="flex flex-col items-center justify-between space-x-0 space-y-3 py-4 sm:flex-row sm:space-x-2 sm:space-y-0">
                <div className="flex-1 text-sm text-muted-foreground">
                    {paginatedTableDisplayMessage(currentPage, proposalListData)}
                </div>
                <div className="flex items-center space-x-2">
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleChangePage('previous')}
                        disabled={!proposalListData?.previous}
                        aria-label="Página anterior"
                    >
                        ← Anterior
                    </Button>
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleChangePage('next')}
                        disabled={!proposalListData?.next}
                        aria-label="Próxima página"
                    >
                        Próximo →
                    </Button>
                </div>
            </div>
        </div>
    );
}

'use client';

import { ErrorMessageBox } from '@/components/ErrorMessage/ErrorMessageBox';
import { Button } from '@/components/ui/button';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { TooltipProvider } from '@/components/ui/tooltip';
import { APP_ROUTES } from '@/constants/app-routes';
import { cn } from '@/lib/utils';
import { BrokerUltralightResults } from '@/types/broker';
import { paginatedTableDisplayMessage } from '@/utils/paginatedTableDisplayMessage';
import {
    flexRender,
    getCoreRowModel,
    getFilteredRowModel,
    getPaginationRowModel,
    getSortedRowModel,
    useReactTable,
} from '@tanstack/react-table';
import { MousePointerClick } from 'lucide-react';
import Link from 'next/link';
import { useProposalList } from '../ProposalListWrapper';
import { BrokerInfoTableSkeleton } from '../Skeletons';
import { brokerInfoTableColumnsUltralight } from './TableColumnsUltralight';

export function BrokerInfoTable() {
    const {
        proposalListData,
        isLoading,
        isError,
        isRefetching,
        refetch,
        currentPage,
        handleChangePage,
    } = useProposalList();
    const table = useReactTable({
        data: (proposalListData?.results as BrokerUltralightResults[]) || [],
        columns: brokerInfoTableColumnsUltralight,
        getCoreRowModel: getCoreRowModel(),
        getPaginationRowModel: getPaginationRowModel(),
        getSortedRowModel: getSortedRowModel(),
        getFilteredRowModel: getFilteredRowModel(),
        initialState: {
            pagination: {
                pageSize: 10,
            },
        },
    });

    if (isLoading) return <BrokerInfoTableSkeleton />;

    return (
        <div className="w-full">
            <TooltipProvider delayDuration={100}>
                <Table className="min-w-[980px] pb-5">
                    <TableHeader>
                        {table.getHeaderGroups().map((headerGroup) => (
                            <TableRow
                                key={headerGroup.id}
                                className="bg-slate-50 text-left text-xs font-semibold uppercase hover:bg-slate-50 dark:bg-boxdark-2 dark:hover:bg-boxdark-2"
                            >
                                {headerGroup.headers.map((header) => (
                                    <TableHead
                                        key={header.id}
                                        className="first:rounded-tl-xl last:rounded-tr-xl"
                                    >
                                        {flexRender(
                                            header.column.columnDef.header,
                                            header.getContext(),
                                        )}
                                    </TableHead>
                                ))}
                            </TableRow>
                        ))}
                    </TableHeader>
                    <TableBody>
                        {proposalListData && table?.getRowModel()?.rows?.length ? (
                            table.getRowModel().rows.map((row) => {
                                const hasPendencies = row.original.status === 'Pendência a Sanar';
                                return (
                                    <TableRow
                                        className={cn(
                                            'group/broker-table-row relative cursor-pointer transition-colors hover:bg-slate-50 dark:hover:bg-slate-800/50',
                                            hasPendencies &&
                                            'bg-red-50/50 hover:bg-red-50 dark:bg-red-950/10 dark:hover:bg-red-950/20',
                                        )}
                                        key={row.id}
                                    >
                                        {row.getVisibleCells().map((cell) => (
                                            <TableCell key={cell.id} className="relative">
                                                {flexRender(
                                                    cell.column.columnDef.cell,
                                                    cell.getContext(),
                                                )}
                                            </TableCell>
                                        ))}
                                        <TableCell className="pointer-events-none absolute inset-0 p-0">
                                            <Link
                                                href={APP_ROUTES.private.brokerOficioDetails.name(
                                                    row.original.extrato_id,
                                                )}
                                                className="pointer-events-auto absolute inset-0 flex items-center justify-center gap-2 bg-zinc-100/10 text-white opacity-0 backdrop-blur-[2px] transition-opacity duration-300 group-hover/broker-table-row:opacity-100 dark:bg-slate-900/10"
                                            >
                                                <MousePointerClick
                                                    size={16}
                                                    className="text-black-2 dark:text-snow"
                                                />
                                                <span className="text-sm font-medium text-black-2 dark:text-snow">
                                                    Clique aqui para continuar a negociação do
                                                    precatório
                                                </span>
                                            </Link>
                                        </TableCell>
                                    </TableRow>
                                );
                            })
                        ) : (
                            <TableRow>
                                <TableCell colSpan={8} className="h-24 text-center">
                                    {proposalListData?.results.length === 0 && (
                                        <span className="animate-fade">
                                            Nenhum registro encontrado
                                        </span>
                                    )}
                                    {isError && (
                                        <ErrorMessageBox
                                            className="border-0 shadow-none"
                                            retryFn={refetch}
                                            isRetrying={isRefetching}
                                        />
                                    )}
                                </TableCell>
                            </TableRow>
                        )}
                    </TableBody>
                </Table>
            </TooltipProvider>

            {proposalListData && (
                <div className="flex flex-col items-center justify-between space-x-0 space-y-3 py-4 sm:flex-row sm:space-x-2 sm:space-y-0">
                    <div className="flex-1 text-sm text-muted-foreground">
                        {paginatedTableDisplayMessage(currentPage, proposalListData)}
                    </div>
                    <div className="flex items-center space-x-2">
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleChangePage('previous')}
                            disabled={!proposalListData?.previous}
                            aria-label="Página anterior"
                        >
                            ← Anterior
                        </Button>
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleChangePage('next')}
                            disabled={!proposalListData?.next}
                            aria-label="Próxima página"
                        >
                            Próximo →
                        </Button>
                    </div>
                </div>
            )}
        </div>
    );
}

