32	    Pencil,
33	    Plus,
34	    RotateCcw,
35	    Settings2,
36	    ShieldCheck,
37	    TrendingUp,
38	    Trophy,
39	    Users,
40	    Volume2,
41	    Zap,
42	} from 'lucide-react';
43	import Link from 'next/link';
44	import { useEffect, useId, useState } from 'react';
45	
46	import {
47	    ConfiguracoesActionRow,
48	    ConfiguracoesSection,
49	    ConfiguracoesThemeRow,
50	    ConfiguracoesToggleRow,
51	} from './_components/configuracoes-ui';
52	import { NotificationPreferencesPanel } from './_components/NotificationPreferencesPanel';
53	import { TwoFactorCard } from './_components/TwoFactorCard';
54	import { getConfiguracoesCanvasStyle, getConfiguracoesPanelStyle } from './_lib/configuracoes-shared';
55	import { canAccessGruposCompartilhamento } from './grupos-compartilhamento/_lib/grupos-compartilhamento-access';
56	import { ScenariosModalType, ScenariosProjectionModalProps } from './types';
57	
58	export default function ConfiguracoesPage() {
59	    const {
60	        preferences,
61	        setShowMessageNotifications,
62	        setShowGamification,
63	        setParticipaRanking,
64	        setPlaySounds,
65	        setExpandSidebarSections,
66	        resetToDefaults,
67	        resetBrokerDashboardLayout,
68	    } = useUserPreferencesStore();
69	
70	    const userInfo = useUserInfoStore((s) => s.data);
71	    const canViewScenarios = userInfo?.role === 'MASTER' || userInfo?.role === 'DEV';
72	    const canViewAiStudio = userInfo?.role === 'MASTER';
73	    const canManageBrokerDashboardLayout = userInfo?.role === 'COMERCIAL_BROKER';
74	    const canManageOperationalTriggersPage = useCanAccessOperationalTriggersScreen({
75	        host: userInfo?.host,
76	        role: userInfo?.role,
77	        isSuperuser: userInfo?.is_superuser,
78	    });
79	    const canManageSharingGroups = canAccessGruposCompartilhamento({
80	        role: userInfo?.role,
81	        isSuperuser: userInfo?.is_superuser,
82	    });
83	
84	    const [modalStates, setModalStates] = useState<ScenariosProjectionModalProps>({
85	        isOpen: false,
86	        modalType: null,
87	    });
88	    const [indexRulesCreateOpen, setIndexRulesCreateOpen] = useState(false);
89	    const [indexRulesListOpen, setIndexRulesListOpen] = useState(false);
90	    const [resetDialogOpen, setResetDialogOpen] = useState(false);
91	    const [resetBrokerLayoutDialogOpen, setResetBrokerLayoutDialogOpen] = useState(false);
92	
93	    const messageNotificationsId = useId();
94	    const gamificationId = useId();
95	    const rankingId = useId();
96	    const soundsId = useId();
97	    const sidebarId = useId();
98	    const themeId = useId();
99	
100	    function handleOpenModal(type: ScenariosModalType) {
101	        setModalStates({ isOpen: true, modalType: type });
102	    }
103	
104	    function handleCloseModal() {
105	        setModalStates({ isOpen: false, modalType: null });
106	    }
107	
108	    useEffect(() => {
109	        let mounted = true;
110	        (async () => {
111	            const data = await getParticipaRanking();
112	            if (!mounted) return;
113	            if (typeof data?.participa_ranking === 'boolean') {
114	                setParticipaRanking(data.participa_ranking);
115	            }
116	        })();
117	        return () => {
118	            mounted = false;
119	        };
120	    }, [setParticipaRanking]);
121	
122	    const handleParticipaRankingChange = async (checked: boolean) => {
123	        const previous = preferences.notifications.participaRanking;
124	        setParticipaRanking(checked);
125	        const toastId = sendToastMessage({ title: 'Salvando preferência...', type: 'loading' });
126	        try {
127	            await updateParticipaRanking(checked);
128	            sendToastMessage({
129	                title: 'Preferência atualizada com sucesso.',
130	                type: 'success',
131	                previousToastId: toastId,
132	            });
133	        } catch {
134	            setParticipaRanking(previous);
135	            sendToastMessage({
136	                title: 'Não foi possível atualizar a preferência.',
137	                type: 'error',
138	                previousToastId: toastId,
139	            });
140	        }
141	    };
142	
143	    function handleConfirmReset() {
144	        resetToDefaults();
145	        setResetDialogOpen(false);
146	        sendToastMessage({ title: 'Preferências restauradas ao padrão.', type: 'success' });
147	    }
148	
149	    function handleConfirmBrokerLayoutReset() {
150	        resetBrokerDashboardLayout();
151	        setResetBrokerLayoutDialogOpen(false);
152	        sendToastMessage({
153	            title: 'Layout do CRM Broker restaurado ao padrão.',
154	            type: 'success',
155	        });
156	    }
157	
158	    return (
159	        <>
160	            <div
161	                className="rounded-2xl border p-4 md:p-5"
162	                style={getConfiguracoesPanelStyle()}
163	            >
164	                <ContentHeader
165	                    title="Configurações"
166	                    subtitle="Preferências pessoais de notificação, interface e ferramentas administrativas."
167	                    icon={Settings2}
168	                    iconContainerClassName="rounded-xl"
169	                    iconStyle={{ color: COLORS.warning }}
170	                    iconContainerStyle={{
171	                        background: withAlpha(COLORS.warning, 0.12),
172	                        border: `1px solid ${withAlpha(COLORS.warning, 0.22)}`,
173	                    }}
174	                />
175	            </div>
176	
177	            <div
178	                className="mt-6 space-y-6 rounded-2xl border p-4 md:p-6"
179	                style={getConfiguracoesCanvasStyle()}
180	            >
181	                <TwoFactorCard />
182	
183	                <NotificationPreferencesPanel />
184	
185	                <ConfiguracoesSection
186	                    title="Notificações"
187	                    description="Escolha quais avisos o Celer pode exibir durante o seu dia de trabalho."
188	                    icon={Bell}
189	                    accentColor={COLORS.brand}
190	                >
191	                    <ConfiguracoesToggleRow
192	                        controlId={messageNotificationsId}
193	                        icon={Bell}
194	                        title="Mensagens do chat"
195	                        description="Avisar quando chegar uma nova mensagem."
196	                        checked={preferences.notifications.showMessageNotifications}
197	                        onCheckedChange={setShowMessageNotifications}
198	                    />
199	                    <ConfiguracoesToggleRow
200	                        controlId={gamificationId}
201	                        icon={Gamepad2}
202	                        title="Gamificação"
203	                        description="Conquistas, XP e progresso de nível."
204	                        checked={preferences.notifications.showGamification}
205	                        onCheckedChange={setShowGamification}
206	                        accentColor={COLORS.success}
207	                    />
208	                    <ConfiguracoesToggleRow
209	                        controlId={rankingId}
210	                        icon={Trophy}
211	                        title="Rankings e conquistas públicas"
212	                        description="Permite aparecer em rankings e exibir conquistas para outras pessoas."
213	                        checked={preferences.notifications.participaRanking}
214	                        onCheckedChange={handleParticipaRankingChange}
215	                        accentColor={COLORS.warning}
216	                    />
217	                    <ConfiguracoesToggleRow
218	                        controlId={soundsId}
219	                        icon={Volume2}
220	                        title="Sons de notificação"
221	                        description="Reproduzir um som curto ao receber avisos."
222	                        checked={preferences.notifications.playSounds}
223	                        onCheckedChange={setPlaySounds}
224	                    />
225	                </ConfiguracoesSection>
226	
227	                <ConfiguracoesSection
228	                    title="Interface"
229	                    description="Ajuste aparência, tema e comportamento do menu para você."
230	                    icon={Monitor}
231	                >
232	                    <ConfiguracoesThemeRow controlId={themeId} />
233	                    <ConfiguracoesToggleRow
234	                        controlId={sidebarId}
235	                        icon={PanelLeftOpen}
236	                        title="Expandir menus da sidebar"
237	                        description="Manter seções do menu lateral abertas por padrão."
238	                        checked={preferences.display.expandSidebarSections}
239	                        onCheckedChange={setExpandSidebarSections}
240	                    />
241	                    {canManageBrokerDashboardLayout && (
242	                        <ConfiguracoesActionRow
243	                            icon={LayoutGrid}
244	                            title="Layout do CRM Broker"
245	                            description="Volte os widgets do dashboard broker ao arranjo inicial. Sincroniza em todos os dispositivos."
246	                            accentColor={COLORS.brandDeep}
247	                            action={(
248	                                <Button
249	                                    type="button"
250	                                    variant="outline"
251	                                    className="h-9 rounded-lg font-satoshi text-sm font-semibold"
252	                                    onClick={() => setResetBrokerLayoutDialogOpen(true)}
253	                                >
254	                                    Restaurar
255	                                </Button>
256	                            )}
257	                        />
258	                    )}
259	                </ConfiguracoesSection>
260	
261	                {canViewScenarios && (
262	                    <ConfiguracoesSection
263	                        title="Cenários de projeções"
264	                        description="Parâmetros de pós-aquisição usados em simulações e relatórios."
265	                        icon={TrendingUp}
266	                        accentColor={COLORS.brandDeep}
267	                    >
268	                        <ConfiguracoesActionRow
269	                            icon={Plus}
270	                            title="Criar cenários"
271	                            description="Defina valores base e datas para novos cenários de projeção."
272	                            action={(
273	                                <Button
274	                                    type="button"
275	                                    variant="outline"
276	                                    className="h-9 rounded-lg font-satoshi text-sm font-semibold"
277	                                    onClick={() => handleOpenModal('create')}
278	                                >
279	                                    Criar
280	                                </Button>
281	                            )}
282	                        />
283	                        <ConfiguracoesActionRow
284	                            icon={Pencil}
285	                            title="Editar cenários"
286	                            description="Revise ou ajuste cenários já cadastrados."
287	                            action={(
288	                                <Button
289	                                    type="button"
290	                                    variant="outline"
291	                                    className="h-9 rounded-lg font-satoshi text-sm font-semibold"
292	                                    onClick={() => handleOpenModal('edit')}
293	                                >
294	                                    Exibir cenários
295	                                </Button>
296	                            )}
297	                        />
298	                    </ConfiguracoesSection>
299	                )}
300	
301	                {canViewScenarios && (
302	                    <ConfiguracoesSection
303	                        title="Regras de índices"
304	                        description="Índices aplicados nos cálculos de pós-aquisição."
305	                        icon={LineChart}
306	                    >
