'use client';

import { ContentHeader } from '@/components/Header/ContentHeader';
import { EditProjectionScenariosModal } from '@/components/Modals/EditProjectionScenariosModal';
import { IndexRulesListModal } from '@/components/Modals/IndexRulesListModal';
import { IndexRulesModal } from '@/components/Modals/IndexRulesModal';
import { NewProjectionModal } from '@/components/Modals/NewProjectionModal';
import { Button } from '@/components/ui/button';
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from '@/components/ui/dialog';
import { APP_ROUTES } from '@/constants/app-routes';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { useCanAccessOperationalTriggersScreen } from '@/hooks/use-can-access-operational-triggers';
import { getParticipaRanking, updateParticipaRanking } from '@/services/users';
import { useUserInfoStore } from '@/store/userInfo';
import { useUserPreferencesStore } from '@/store/useUserPreferencesStore';
import { COLORS, TYPOGRAPHY, withAlpha } from '@/design-system';
import {
    Bell,
    Bot,
    Gamepad2,
    LayoutGrid,
    LineChart,
    Monitor,
    PanelLeftOpen,
    Pencil,
    Plus,
    RotateCcw,
    Settings2,
    ShieldCheck,
    TrendingUp,
    Trophy,
    Users,
    Volume2,
    Zap,
} from 'lucide-react';
import Link from 'next/link';
import { useEffect, useId, useState } from 'react';

import {
    ConfiguracoesActionRow,
    ConfiguracoesSection,
    ConfiguracoesThemeRow,
    ConfiguracoesToggleRow,
} from './_components/configuracoes-ui';
import { NotificationPreferencesPanel } from './_components/NotificationPreferencesPanel';
import { TwoFactorCard } from './_components/TwoFactorCard';
import { getConfiguracoesCanvasStyle, getConfiguracoesPanelStyle } from './_lib/configuracoes-shared';
import { canAccessGruposCompartilhamento } from './grupos-compartilhamento/_lib/grupos-compartilhamento-access';
import { ScenariosModalType, ScenariosProjectionModalProps } from './types';

export default function ConfiguracoesPage() {
    const {
        preferences,
        setShowMessageNotifications,
        setShowGamification,
        setParticipaRanking,
        setPlaySounds,
        setExpandSidebarSections,
        resetToDefaults,
        resetBrokerDashboardLayout,
    } = useUserPreferencesStore();

    const userInfo = useUserInfoStore((s) => s.data);
    const canViewScenarios = userInfo?.role === 'MASTER' || userInfo?.role === 'DEV';
    const canViewAiStudio = userInfo?.role === 'MASTER';
    const canManageBrokerDashboardLayout = userInfo?.role === 'COMERCIAL_BROKER';
    const canManageOperationalTriggersPage = useCanAccessOperationalTriggersScreen({
        host: userInfo?.host,
        role: userInfo?.role,
        isSuperuser: userInfo?.is_superuser,
    });
    const canManageSharingGroups = canAccessGruposCompartilhamento({
        role: userInfo?.role,
        isSuperuser: userInfo?.is_superuser,
    });

    const [modalStates, setModalStates] = useState<ScenariosProjectionModalProps>({
        isOpen: false,
        modalType: null,
    });
    const [indexRulesCreateOpen, setIndexRulesCreateOpen] = useState(false);
    const [indexRulesListOpen, setIndexRulesListOpen] = useState(false);
    const [resetDialogOpen, setResetDialogOpen] = useState(false);
    const [resetBrokerLayoutDialogOpen, setResetBrokerLayoutDialogOpen] = useState(false);

    const messageNotificationsId = useId();
    const gamificationId = useId();
    const rankingId = useId();
    const soundsId = useId();
    const sidebarId = useId();
    const themeId = useId();

    function handleOpenModal(type: ScenariosModalType) {
        setModalStates({ isOpen: true, modalType: type });
    }

    function handleCloseModal() {
        setModalStates({ isOpen: false, modalType: null });
    }

    useEffect(() => {
        let mounted = true;
        (async () => {
            const data = await getParticipaRanking();
            if (!mounted) return;
            if (typeof data?.participa_ranking === 'boolean') {
                setParticipaRanking(data.participa_ranking);
            }
        })();
        return () => {
            mounted = false;
        };
    }, [setParticipaRanking]);

    const handleParticipaRankingChange = async (checked: boolean) => {
        const previous = preferences.notifications.participaRanking;
        setParticipaRanking(checked);
        const toastId = sendToastMessage({ title: 'Salvando preferência...', type: 'loading' });
        try {
            await updateParticipaRanking(checked);
            sendToastMessage({
                title: 'Preferência atualizada com sucesso.',
                type: 'success',
                previousToastId: toastId,
            });
        } catch {
            setParticipaRanking(previous);
            sendToastMessage({
                title: 'Não foi possível atualizar a preferência.',
                type: 'error',
                previousToastId: toastId,
            });
        }
    };

    function handleConfirmReset() {
        resetToDefaults();
        setResetDialogOpen(false);
        sendToastMessage({ title: 'Preferências restauradas ao padrão.', type: 'success' });
    }

    function handleConfirmBrokerLayoutReset() {
        resetBrokerDashboardLayout();
        setResetBrokerLayoutDialogOpen(false);
        sendToastMessage({
            title: 'Layout do CRM Broker restaurado ao padrão.',
            type: 'success',
        });
    }

    return (
        <>
            <div
                className="rounded-2xl border p-4 md:p-5"
                style={getConfiguracoesPanelStyle()}
            >
                <ContentHeader
                    title="Configurações"
                    subtitle="Preferências pessoais de notificação, interface e ferramentas administrativas."
                    icon={Settings2}
                    iconContainerClassName="rounded-xl"
                    iconStyle={{ color: COLORS.warning }}
                    iconContainerStyle={{
                        background: withAlpha(COLORS.warning, 0.12),
                        border: `1px solid ${withAlpha(COLORS.warning, 0.22)}`,
                    }}
                />
            </div>

            <div
                className="mt-6 space-y-6 rounded-2xl border p-4 md:p-6"
                style={getConfiguracoesCanvasStyle()}
            >
                <TwoFactorCard />

                <NotificationPreferencesPanel />

                <ConfiguracoesSection
                    title="Notificações"
                    description="Escolha quais avisos o Celer pode exibir durante o seu dia de trabalho."
                    icon={Bell}
                    accentColor={COLORS.brand}
                >
                    <ConfiguracoesToggleRow
                        controlId={messageNotificationsId}
                        icon={Bell}
                        title="Mensagens do chat"
                        description="Avisar quando chegar uma nova mensagem."
                        checked={preferences.notifications.showMessageNotifications}
                        onCheckedChange={setShowMessageNotifications}
                    />
                    <ConfiguracoesToggleRow
                        controlId={gamificationId}
                        icon={Gamepad2}
                        title="Gamificação"
                        description="Conquistas, XP e progresso de nível."
                        checked={preferences.notifications.showGamification}
                        onCheckedChange={setShowGamification}
                        accentColor={COLORS.success}
                    />
                    <ConfiguracoesToggleRow
                        controlId={rankingId}
                        icon={Trophy}
                        title="Rankings e conquistas públicas"
                        description="Permite aparecer em rankings e exibir conquistas para outras pessoas."
                        checked={preferences.notifications.participaRanking}
                        onCheckedChange={handleParticipaRankingChange}
                        accentColor={COLORS.warning}
                    />
                    <ConfiguracoesToggleRow
                        controlId={soundsId}
                        icon={Volume2}
                        title="Sons de notificação"
                        description="Reproduzir um som curto ao receber avisos."
                        checked={preferences.notifications.playSounds}
                        onCheckedChange={setPlaySounds}
                    />
                </ConfiguracoesSection>

                <ConfiguracoesSection
                    title="Interface"
                    description="Ajuste aparência, tema e comportamento do menu para você."
                    icon={Monitor}
                >
                    <ConfiguracoesThemeRow controlId={themeId} />
                    <ConfiguracoesToggleRow
                        controlId={sidebarId}
                        icon={PanelLeftOpen}
                        title="Expandir menus da sidebar"
                        description="Manter seções do menu lateral abertas por padrão."
                        checked={preferences.display.expandSidebarSections}
                        onCheckedChange={setExpandSidebarSections}
                    />
                    {canManageBrokerDashboardLayout && (
                        <ConfiguracoesActionRow
                            icon={LayoutGrid}
                            title="Layout do CRM Broker"
                            description="Volte os widgets do dashboard broker ao arranjo inicial. Sincroniza em todos os dispositivos."
                            accentColor={COLORS.brandDeep}
                            action={(
                                <Button
                                    type="button"
                                    variant="outline"
                                    className="h-9 rounded-lg font-satoshi text-sm font-semibold"
                                    onClick={() => setResetBrokerLayoutDialogOpen(true)}
                                >
                                    Restaurar
                                </Button>
                            )}
                        />
                    )}
                </ConfiguracoesSection>

                {canViewScenarios && (
                    <ConfiguracoesSection
                        title="Cenários de projeções"
                        description="Parâmetros de pós-aquisição usados em simulações e relatórios."
                        icon={TrendingUp}
                        accentColor={COLORS.brandDeep}
                    >
                        <ConfiguracoesActionRow
                            icon={Plus}
                            title="Criar cenários"
                            description="Defina valores base e datas para novos cenários de projeção."
                            action={(
                                <Button
                                    type="button"
                                    variant="outline"
                                    className="h-9 rounded-lg font-satoshi text-sm font-semibold"
                                    onClick={() => handleOpenModal('create')}
                                >
                                    Criar
                                </Button>
                            )}
                        />
                        <ConfiguracoesActionRow
                            icon={Pencil}
                            title="Editar cenários"
                            description="Revise ou ajuste cenários já cadastrados."
                            action={(
                                <Button
                                    type="button"
                                    variant="outline"
                                    className="h-9 rounded-lg font-satoshi text-sm font-semibold"
                                    onClick={() => handleOpenModal('edit')}
                                >
                                    Exibir cenários
                                </Button>
                            )}
                        />
                    </ConfiguracoesSection>
                )}

                {canViewScenarios && (
                    <ConfiguracoesSection
                        title="Regras de índices"
                        description="Índices aplicados nos cálculos de pós-aquisição."
                        icon={LineChart}
                    >
                        <ConfiguracoesActionRow
                            icon={Plus}
                            title="Criar regra"
                            description="Cadastre uma regra de índice para um período específico."
                            action={(
                                <Button
                                    type="button"
                                    variant="outline"
                                    className="h-9 rounded-lg font-satoshi text-sm font-semibold"
                                    onClick={() => setIndexRulesCreateOpen(true)}
                                >
                                    Criar
                                </Button>
                            )}
                        />
                        <ConfiguracoesActionRow
                            icon={Pencil}
                            title="Gerenciar regras"
                            description="Visualize, edite ou remova regras existentes."
                            action={(
                                <Button
                                    type="button"
                                    variant="outline"
                                    className="h-9 rounded-lg font-satoshi text-sm font-semibold"
                                    onClick={() => setIndexRulesListOpen(true)}
                                >
                                    Exibir regras
                                </Button>
                            )}
                        />
                    </ConfiguracoesSection>
                )}

                {canViewAiStudio && (
                    <ConfiguracoesSection
                        title="Ativos Intelligence Studio"
                        description="Governança de conhecimento por agente, com varredura e auditoria antes da ativação."
                        icon={ShieldCheck}
                        accentColor={COLORS.brand}
                    >
                        <ConfiguracoesActionRow
                            icon={Bot}
                            title="Knowledge Studio"
                            description="Envie bases por agente e ative somente o que passou na validação."
                            action={(
                                <Button
                                    type="button"
                                    variant="outline"
                                    className="h-9 rounded-lg font-satoshi text-sm font-semibold"
                                    asChild
                                >
                                    <Link href="/configuracoes/ativos-intelligence">Abrir studio</Link>
                                </Button>
                            )}
                        />
                    </ConfiguracoesSection>
                )}

                {canManageOperationalTriggersPage && (
                    <ConfiguracoesSection
                        title="Automação operacional"
                        description="Gatilhos que disparam notificações, tarefas e integrações em eventos do Celer."
                        icon={Zap}
                        accentColor={COLORS.brand}
                    >
                        <ConfiguracoesActionRow
                            icon={Zap}
                            title="Gatilhos Operacionais"
                            description="Configure avisos ao setor de Liquidação e outras ações automáticas."
                            action={(
                                <Button
                                    type="button"
                                    variant="outline"
                                    className="h-9 rounded-lg font-satoshi text-sm font-semibold"
                                    asChild
                                >
                                    <Link href={APP_ROUTES.private.gatilhosOperacionais.name}>Abrir</Link>
                                </Button>
                            )}
                        />
                    </ConfiguracoesSection>
                )}

                {canManageSharingGroups && (
                    <ConfiguracoesSection
                        title="Compartilhamento Due"
                        description="Equipes reutilizáveis que entram no link público sem código de verificação."
                        icon={Users}
                        accentColor={COLORS.brand}
                    >
                        <ConfiguracoesActionRow
                            icon={Users}
                            title="Grupos de compartilhamento"
                            description="Crie e edite equipes (ex.: Equipe DASI) com e-mail e CPF. Vale em todos os links do host."
                            action={(
                                <Button
                                    type="button"
                                    variant="outline"
                                    className="h-9 rounded-lg font-satoshi text-sm font-semibold"
                                    asChild
                                >
                                    <Link href={APP_ROUTES.private.configuracoesGruposCompartilhamento.name}>
                                        Gerenciar
                                    </Link>
                                </Button>
                            )}
                        />
                    </ConfiguracoesSection>
                )}

                <ConfiguracoesSection
                    title="Restaurar padrões"
                    description="Volte notificações e interface para os valores iniciais do sistema."
                    icon={RotateCcw}
                    accentColor={COLORS.textDim}
                >
                    <ConfiguracoesActionRow
                        icon={RotateCcw}
                        title="Restaurar preferências"
                        description="Esta ação não altera dados de conta, 2FA nem configurações globais."
                        action={(
                            <Button
                                type="button"
                                variant="outline"
                                className="h-9 rounded-lg font-satoshi text-sm font-semibold"
                                onClick={() => setResetDialogOpen(true)}
                            >
                                Restaurar
                            </Button>
                        )}
                    />
                </ConfiguracoesSection>
            </div>

            <Dialog open={resetDialogOpen} onOpenChange={setResetDialogOpen}>
                <DialogContent className="max-w-md rounded-2xl font-satoshi">
                    <DialogHeader>
                        <DialogTitle className={TYPOGRAPHY.title}>Restaurar preferências?</DialogTitle>
                        <DialogDescription className={TYPOGRAPHY.body} style={{ color: COLORS.textDim }}>
                            Notificações e opções de interface voltam ao padrão. Preferências de documentos e
                            segurança não são alteradas.
                        </DialogDescription>
                    </DialogHeader>
                    <DialogFooter className="gap-2 sm:gap-2">
                        <Button type="button" variant="outline" onClick={() => setResetDialogOpen(false)}>
                            Cancelar
                        </Button>
                        <Button type="button" onClick={handleConfirmReset}>
                            Restaurar padrões
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {canManageBrokerDashboardLayout && (
                <Dialog open={resetBrokerLayoutDialogOpen} onOpenChange={setResetBrokerLayoutDialogOpen}>
                    <DialogContent className="max-w-md rounded-2xl font-satoshi">
                        <DialogHeader>
                            <DialogTitle className={TYPOGRAPHY.title}>
                                Restaurar layout do CRM Broker?
                            </DialogTitle>
                            <DialogDescription className={TYPOGRAPHY.body} style={{ color: COLORS.textDim }}>
                                Os widgets voltam ao arranjo padrão. Se o dashboard estiver aberto, a
                                alteração aparece na hora; caso contrário, na próxima visita.
                            </DialogDescription>
                        </DialogHeader>
                        <DialogFooter className="gap-2 sm:gap-2">
                            <Button
                                type="button"
                                variant="outline"
                                onClick={() => setResetBrokerLayoutDialogOpen(false)}
                            >
                                Cancelar
                            </Button>
                            <Button type="button" onClick={handleConfirmBrokerLayoutReset}>
                                Restaurar layout
                            </Button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            )}

            {modalStates.isOpen && modalStates.modalType === 'create' && (
                <NewProjectionModal isOpen={modalStates.isOpen} onClose={handleCloseModal} />
            )}
            {modalStates.isOpen && modalStates.modalType === 'edit' && (
                <EditProjectionScenariosModal isOpen={modalStates.isOpen} onClose={handleCloseModal} />
            )}
            <IndexRulesModal isOpen={indexRulesCreateOpen} onClose={() => setIndexRulesCreateOpen(false)} />
            <IndexRulesListModal isOpen={indexRulesListOpen} onClose={() => setIndexRulesListOpen(false)} />
        </>
    );
}

