'use client';

import { useTopNotchClipPath } from '@/hooks/useTopNotchClipPath';
import { cn } from '@/lib/utils';
import { parseAsString, parseAsStringLiteral, useQueryState, useQueryStates } from 'nuqs';
import { useCallback, useRef } from 'react';
import { usePathname, useRouter, useSearchParams } from 'next/navigation';
import { AnimatedTabs, AnimatedTabsContent } from '../ui/animated-tabs';
import { JuridicalView } from './JuridicalView';
import { DashboardWrapper } from './financial/DashboardWrapper';
import { IndividualCardsWrapper } from './financial/IndividualCards/IndividualCardsWrapper';
import {
    buildFinancialEditHref,
    buildFinancialListReturnTo,
    buildFinancialNewHref,
    FINANCIAL_ATIVO_PARAM,
    FINANCIAL_TAB_PARAM,
    FINANCIAL_TAB_VALUE,
} from '@/functions/post-purchase/financial-return-navigation';

const TAB_VALUES = ['financial-view', 'juridical-view'] as const;
type TNewPostPurchaseTab = (typeof TAB_VALUES)[number];

const TAB_LABELS: Record<TNewPostPurchaseTab, { short: string; full: string }> = {
    'financial-view': { short: 'Financeira', full: 'Visão Financeira' },
    'juridical-view': { short: 'Jurídica', full: 'Visão Jurídica' },
};

export function NewPostPurchase() {
    const router = useRouter();
    const pathname = usePathname();
    const searchParams = useSearchParams();
    const [activeTab, setActiveTab] = useQueryState(
        'tab',
        parseAsStringLiteral(TAB_VALUES).withDefault('financial-view'),
    );

    const topNotchRef = useRef<HTMLDivElement>(null);
    useTopNotchClipPath({ notchRef: topNotchRef, notchWidth: 290 });

    const [dashboardUrlFilters, setDashboardUrlFilters] = useQueryStates({
        cenario_rentabilidade: parseAsString,
        view_type: parseAsString.withDefault('projetado'),
    });

    const [cardsUrlFilters, setCardsUrlFilters] = useQueryStates({
        credor: parseAsString,
        cessionario: parseAsString,
        cedente: parseAsString,
        estado_ente_devedor: parseAsString,
        loa: parseAsString,
        esfera: parseAsString,
        natureza: parseAsString,
        ente_devedor: parseAsString,
        data_aquisicao: parseAsString,
        data_prev_pag: parseAsString,
        data_transmissao: parseAsString,
        valor_liquido: parseAsString,
        revisado: parseAsString,
        importado: parseAsString,
    });

    const handleEditItem = useCallback(
        (itemId: string) => {
            const returnTo = buildFinancialListReturnTo(pathname, searchParams, {
                [FINANCIAL_ATIVO_PARAM]: itemId,
                [FINANCIAL_TAB_PARAM]: FINANCIAL_TAB_VALUE,
            });
            router.push(buildFinancialEditHref(itemId, returnTo));
        },
        [pathname, router, searchParams],
    );

    const handleNewItemFromFinancial = useCallback(() => {
        const returnTo = buildFinancialListReturnTo(pathname, searchParams, {
            [FINANCIAL_TAB_PARAM]: FINANCIAL_TAB_VALUE,
        });
        router.push(buildFinancialNewHref(returnTo));
    }, [pathname, router, searchParams]);

    return (
        <div className="min-w-0 max-w-full overflow-x-hidden bg-celer-panel dark:bg-celer-ink">
            <AnimatedTabs
                id="new-post-purchase-tabs"
                value={activeTab}
                onValueChange={(value) => setActiveTab(value as TNewPostPurchaseTab)}
                defaultValue="financial-view"
            >
                {/* Notch superior de troca de visão */}
                <div className="relative z-10 w-full min-w-0 overflow-hidden border-b border-celer-line/60 bg-celer-paper px-3 py-2.5 dark:border-white/10 dark:bg-celer-graphite sm:border-0 sm:bg-transparent sm:px-4 sm:py-1 dark:sm:bg-transparent">
                    <div
                        ref={topNotchRef}
                        className="pointer-events-none absolute inset-0 hidden bg-celer-paper sm:block dark:bg-celer-graphite"
                        aria-hidden
                    />
                    <div className="relative z-5 flex w-full items-center gap-1.5 sm:justify-center sm:gap-0">
                        {/* Slot: voltar (portal do detalhe) — flex no mobile, absoluto no sm+ */}
                        <div
                            id="pos-aq-notch-back"
                            className="pointer-events-auto z-6 flex shrink-0 items-center justify-start empty:hidden sm:absolute sm:left-0 sm:top-1/2 sm:block sm:-translate-y-1/2 sm:empty:block"
                        />

                        <div
                            role="tablist"
                            aria-label="Alternar entre visão financeira e jurídica"
                            className="grid min-w-0 flex-1 grid-cols-2 gap-0.5 overflow-hidden rounded-full bg-celer-panel/50 p-0.5 dark:bg-celer-slate/60 sm:w-[min(100%,290px)] sm:max-w-[290px] sm:flex-none sm:gap-1 sm:p-1"
                        >
                            {TAB_VALUES.map((tab) => {
                                const isActive = activeTab === tab;
                                const labels = TAB_LABELS[tab];

                                return (
                                    <button
                                        key={tab}
                                        type="button"
                                        role="tab"
                                        aria-selected={isActive}
                                        onClick={() => setActiveTab(tab)}
                                        className={cn(
                                            'flex h-8 min-w-0 items-center justify-center overflow-hidden rounded-full px-1.5 text-center text-[11px] font-semibold leading-none transition-colors duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-celer-blue/45 focus-visible:ring-inset motion-reduce:transition-none sm:h-[30px] sm:px-2.5',
                                            isActive
                                                ? tab === 'juridical-view'
                                                    ? 'bg-celer-blue text-white'
                                                    : 'bg-[#96FF00] text-[#0b1404]'
                                                : 'text-celer-muted hover:text-celer-strong dark:text-muted-foreground dark:hover:text-foreground',
                                        )}
                                    >
                                        <span className="block w-full truncate sm:hidden">
                                            {labels.short}
                                        </span>
                                        <span className="hidden w-full truncate sm:block">
                                            {labels.full}
                                        </span>
                                    </button>
                                );
                            })}
                        </div>

                        {/* Slot: Litígios · Due Diligence · Comentários — flex no mobile, absoluto no sm+ */}
                        <div
                            id="pos-aq-notch-actions"
                            className="pointer-events-auto z-6 flex shrink-0 items-center justify-end empty:hidden sm:absolute sm:right-0 sm:top-1/2 sm:block sm:max-w-[min(100%,420px)] sm:-translate-y-1/2 sm:empty:block"
                        />
                    </div>
                </div>

                <AnimatedTabsContent value="financial-view" className="space-y-6">
                    <DashboardWrapper
                        dashboardUrlFilters={dashboardUrlFilters}
                        setDashboardUrlFilters={setDashboardUrlFilters}
                        selectedCessionario={cardsUrlFilters.cessionario}
                        onCessionarioSelect={(nome) => setCardsUrlFilters({ cessionario: nome })}
                        selectedEnteDevedor={cardsUrlFilters.ente_devedor}
                        onEnteDevedorSelect={(nome) => setCardsUrlFilters({ ente_devedor: nome })}
                    />
                    <IndividualCardsWrapper
                        urlFilters={cardsUrlFilters}
                        setUrlFilters={setCardsUrlFilters}
                        onEditItem={handleEditItem}
                        onNewItem={handleNewItemFromFinancial}
                    />
                </AnimatedTabsContent>
                <AnimatedTabsContent
                    value="juridical-view"
                    className="min-w-0 max-w-full overflow-x-hidden px-4 sm:px-6"
                >
                    <JuridicalView />
                </AnimatedTabsContent>
            </AnimatedTabs>
        </div>
    );
}

