7	import { useUserInfoStore } from '@/store/userInfo';
8	import { ScenariosTableSkeleton } from '@/components/Skeletons/ScenariosTableSkeleton';
9	import { CalculatorIcon, Calendar, Info, Plus } from 'lucide-react';
10	import { Suspense, useState } from 'react';
11	import { sendToastMessage } from '@/functions/messages/toastMessage';
12	import { HistoricResultsModal } from './_components/HistoricResultsModal';
13	import { MonitoryInfoModal } from './_components/MonitoryInfoModal';
14	import { ScenariosTable } from './_components/ScenariosTable';
15	import { useQuery } from '@tanstack/react-query';
16	import { useGetStaffUsersQueryOptions } from '@/hooks/queries/users';
17	import { Scenario } from '@/types/scenario';
18	import { AuditCalculatorPayload } from './types';
19	
20	export default function MonitoramentoCalculadora() {
21	    const { data: userData } = useUserInfoStore();
22	
23	    const [isModalOpen, setIsModalOpen] = useState(false);
24	    const [selectedScenario, setSelectedScenario] = useState<Scenario | null>(null);
25	    const [isResultsModalOpen, setIsResultsModalOpen] = useState(false);
26	
27	    const [inputPayload, setInputPayload] = useState<AuditCalculatorPayload | null>(null);
28	    const [notifiedUsers, setNotifiedUsers] = useState<string[]>([]);
29	    const [selectedIds, setSelectedIds] = useState<string[]>([]);
30	
31	    const { data: superUsers } = useQuery(
32	        useGetStaffUsersQueryOptions({ isEnabled: userData?.is_staff }),
33	    );
34	
35	    const handleBulkAction = async (action: 'delete' | 'activate' | 'deactivate') => {
36	        if (selectedIds.length === 0) return;
37	
38	        const confirmMsg =
39	            action === 'delete'
40	                ? `Tem certeza que deseja excluir ${selectedIds.length} cenários?`
41	                : `Deseja ${action === 'activate' ? 'ativar' : 'desativar'} ${selectedIds.length} cenários?`;
42	
43	        if (!confirm(confirmMsg)) return;
44	
45	        try {
46	            await AuditServices.bulkAction(selectedIds, action);
47	            sendToastMessage({ type: 'success', title: 'Ação realizada com sucesso' });
48	            setSelectedIds([]);
49	        } catch {
50	            sendToastMessage({ type: 'error', title: 'Erro ao realizar ação em lote' });
51	        }
52	    };
53	
54	    const handleViewResults = async (scenario: Scenario) => {
55	        setSelectedScenario(scenario);
56	        setIsResultsModalOpen(true);
57	    };
58	
59	    const openModal = (scenario: Scenario | null = null) => {
60	        setSelectedScenario(scenario);
61	        if (scenario) {
62	            setInputPayload(scenario.input_payload);
63	            setNotifiedUsers((scenario.notified_users || []).map((id) => id.toString()));
64	        } else {
65	            setInputPayload(null);
66	
67	            // Selecionar usuário logado por padrão se for novo cenário
68	            if (userData?.user) {
69	                const currentUser = superUsers?.find((u) => u.username === userData.user);
70	                if (currentUser) {
71	                    setNotifiedUsers([currentUser.id.toString()]);
72	                } else {
73	                    setNotifiedUsers([]);
74	                }
75	            } else {
76	                setNotifiedUsers([]);
77	            }
78	        }
79	        // setFormErrors({});
80	        setIsModalOpen(true);
81	    };
82	
83	    if (!userData?.is_staff) {
84	        return (
85	            <Alert variant="destructive">
86	                <Info className="h-4 w-4" />
87	                <AlertDescription>Acesso restrito a administradores.</AlertDescription>
88	            </Alert>
89	        );
90	    }
91	
92	    return (
93	        <div className="space-y-6">
94	            <div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
95	                <ContentHeader
96	                    title="Monitoramento da Calculadora"
97	                    subtitle="Auditoria automática e integridade de cálculos"
98	                    icon={CalculatorIcon}
99	                />
100	
101	                <div className="flex flex-wrap items-center gap-3">
102	                    <div className="flex items-center gap-2 rounded-lg border border-stroke bg-white px-4 py-2 dark:border-strokedark dark:bg-boxdark">
103	                        <Calendar className="h-5 w-5 text-primary" />
104	                        <span className="text-sm font-medium text-black dark:text-white">
105	                            Checagem: <span className="font-bold text-primary">A cada 6 horas</span>
106	                        </span>
107	                    </div>
108	
109	                    <Button
110	                        variant="default"
111	                        onClick={() => openModal(null)}
112	                        className="flex items-center gap-2 rounded-lg font-medium text-white hover:bg-opacity-90"
113	                    >
114	                        <Plus className="h-5 w-5" />
115	                        Novo Cenário
116	                    </Button>
117	                </div>
118	            </div>
119	
120	            {selectedIds.length > 0 && (
121	                <div className="animate-fade-in mb-6 flex items-center justify-between rounded-lg border border-primary bg-primary/5 p-4 dark:bg-primary/10">
122	                    <div className="flex items-center gap-3">
123	                        <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary text-white">
124	                            <span className="text-sm font-bold">{selectedIds.length}</span>
125	                        </div>
126	                        <div>
127	                            <p className="font-semibold text-black dark:text-white">
128	                                Itens selecionados
129	                            </p>
130	                            <button
131	                                className="text-xs text-primary hover:underline"
132	                                onClick={() => setSelectedIds([])}
133	                            >
134	                                Limpar seleção
135	                            </button>
136	                        </div>
137	                    </div>
138	
139	                    <div className="flex gap-2">
140	                        <Button
141	                            size="sm"
142	                            variant="outline-success"
143	                            onClick={() => handleBulkAction('activate')}
144	                            className="bg-success text-white hover:bg-opacity-90"
145	                        >
146	                            Ativar
147	                        </Button>
148	                        <Button
149	                            size="sm"
150	                            variant="outline-warning"
151	                            onClick={() => handleBulkAction('deactivate')}
152	                            className="bg-warning text-white hover:bg-opacity-90"
153	                        >
