import { ScenariosTable } from './_components/ScenariosTable';
import { useQuery } from '@tanstack/react-query';
import { useGetStaffUsersQueryOptions } from '@/hooks/queries/users';
import { Scenario } from '@/types/scenario';
import { AuditCalculatorPayload } from './types';

export default function MonitoramentoCalculadora() {
    const { data: userData } = useUserInfoStore();

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedScenario, setSelectedScenario] = useState<Scenario | null>(null);
    const [isResultsModalOpen, setIsResultsModalOpen] = useState(false);

    const [inputPayload, setInputPayload] = useState<AuditCalculatorPayload | null>(null);
    const [notifiedUsers, setNotifiedUsers] = useState<string[]>([]);
    const [selectedIds, setSelectedIds] = useState<string[]>([]);

    const { data: superUsers } = useQuery(
        useGetStaffUsersQueryOptions({ isEnabled: userData?.is_staff }),
    );

    const handleBulkAction = async (action: 'delete' | 'activate' | 'deactivate') => {
        if (selectedIds.length === 0) return;

        const confirmMsg =
            action === 'delete'
                ? `Tem certeza que deseja excluir ${selectedIds.length} cenários?`
                : `Deseja ${action === 'activate' ? 'ativar' : 'desativar'} ${selectedIds.length} cenários?`;

        if (!confirm(confirmMsg)) return;

        try {
            await AuditServices.bulkAction(selectedIds, action);
            sendToastMessage({ type: 'success', title: 'Ação realizada com sucesso' });
            setSelectedIds([]);
        } catch {
            sendToastMessage({ type: 'error', title: 'Erro ao realizar ação em lote' });
        }
    };

    const handleViewResults = async (scenario: Scenario) => {
        setSelectedScenario(scenario);
        setIsResultsModalOpen(true);
    };

    const openModal = (scenario: Scenario | null = null) => {
        setSelectedScenario(scenario);
        if (scenario) {
            setInputPayload(scenario.input_payload);
            setNotifiedUsers((scenario.notified_users || []).map((id) => id.toString()));
        } else {
            setInputPayload(null);

            // Selecionar usuário logado por padrão se for novo cenário
            if (userData?.user) {
                const currentUser = superUsers?.find((u) => u.username === userData.user);
                if (currentUser) {
                    setNotifiedUsers([currentUser.id.toString()]);
                } else {
                    setNotifiedUsers([]);
                }
            } else {
                setNotifiedUsers([]);
            }
        }
        // setFormErrors({});
        setIsModalOpen(true);
    };

    if (!userData?.is_staff) {
        return (
            <Alert variant="destructive">
                <Info className="h-4 w-4" />
                <AlertDescription>Acesso restrito a administradores.</AlertDescription>
            </Alert>
        );
    }

    return (
        <div className="space-y-6">
            <div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                <ContentHeader
                    title="Monitoramento da Calculadora"
                    subtitle="Auditoria automática e integridade de cálculos"
                    icon={CalculatorIcon}
                />

                <div className="flex flex-wrap items-center gap-3">
                    <div className="flex items-center gap-2 rounded-lg border border-stroke bg-white px-4 py-2 dark:border-strokedark dark:bg-boxdark">
                        <Calendar className="h-5 w-5 text-primary" />
                        <span className="text-sm font-medium text-black dark:text-white">
                            Checagem: <span className="font-bold text-primary">A cada 6 horas</span>
                        </span>
                    </div>

                    <Button
                        variant="default"
                        onClick={() => openModal(null)}
                        className="flex items-center gap-2 rounded-lg font-medium text-white hover:bg-opacity-90"
                    >
                        <Plus className="h-5 w-5" />
                        Novo Cenário
                    </Button>
                </div>
            </div>

            {selectedIds.length > 0 && (
                <div className="animate-fade-in mb-6 flex items-center justify-between rounded-lg border border-primary bg-primary/5 p-4 dark:bg-primary/10">
                    <div className="flex items-center gap-3">
                        <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary text-white">
                            <span className="text-sm font-bold">{selectedIds.length}</span>
                        </div>
                        <div>
                            <p className="font-semibold text-black dark:text-white">
                                Itens selecionados
                            </p>
                            <button
                                className="text-xs text-primary hover:underline"
                                onClick={() => setSelectedIds([])}
                            >
                                Limpar seleção
                            </button>
                        </div>
                    </div>

                    <div className="flex gap-2">
                        <Button
                            size="sm"
                            variant="outline-success"
                            onClick={() => handleBulkAction('activate')}
                            className="bg-success text-white hover:bg-opacity-90"
                        >
                            Ativar
                        </Button>
                        <Button
                            size="sm"
                            variant="outline-warning"
                            onClick={() => handleBulkAction('deactivate')}
                            className="bg-warning text-white hover:bg-opacity-90"
                        >
                            Desativar
                        </Button>
                        <Button
                            size="sm"
                            variant="outline-danger"
                            onClick={() => handleBulkAction('delete')}
                            className="bg-danger text-white hover:bg-opacity-90"
                        >
                            Excluir
                        </Button>
                    </div>
                </div>
            )}

            <div className="overflow-hidden rounded-md border border-stroke bg-white shadow-default dark:border-strokedark dark:bg-boxdark">
                <Suspense fallback={<ScenariosTableSkeleton />}>
                    <ScenariosTable
                        selectedIds={selectedIds}
                        onSelectIds={setSelectedIds}
                        onViewResults={handleViewResults}
                        onOpenModal={openModal}
                    />
                </Suspense>
            </div>

            {/* Modal de Criação/Edição */}
            {isModalOpen && (
                <MonitoryInfoModal
                    isOpen={isModalOpen}
                    onClose={setIsModalOpen}
                    selectedScenario={selectedScenario}
                    setInputPayload={setInputPayload}
                    inputPayload={inputPayload}
                    notifiedUsers={notifiedUsers}
                    setNotifiedUsers={setNotifiedUsers}
                    superusers={superUsers ?? []}
                />
            )}

            {/* Modal de Resultados */}
            {isResultsModalOpen && (
                <HistoricResultsModal
                    isOpen={isResultsModalOpen}
                    onClose={setIsResultsModalOpen}
                    scenarioId={selectedScenario?.id || ''}
                />
            )}

