'use client';
import { BrokerProposalList } from '@/app/crm/broker/_components/BrokerInfo/Card/List';
import { ProposalListWrapper } from '@/app/crm/broker/_components/BrokerInfo/ProposalListWrapper';
import { BrokerPrecatoriosTable } from '@/app/crm/gerencial-broker/table/data-table';
import { BrokerComissionPreviewChart } from '@/components/Charts/Brokers/BrokerComissionPreviewChart';
import { BrokerQuantityDistribuitionChart } from '@/components/Charts/Brokers/BrokerQuantityDistribuitionChart';
import { canAccessCoordinatorData } from '@/functions/rulesVerification';
import { createBrokerDashboardChartsQueryOptions } from '@/hooks/queries/broker';
import { useIsMobile } from '@/hooks/use-mobile';
import { useBrokerStore } from '@/store/useBroker';
import { useUserInfoStore } from '@/store/userInfo';
import { useQuery } from '@tanstack/react-query';
import { parseAsString, useQueryStates } from 'nuqs';
import { useEffect } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { BrokerCommissionAcquiredChart } from '../../Charts/Brokers/BrokerComissionAcquired';

/**
 * Componente que renderiza o dashboar dos brokers
 * (wrapper principal)
 */

function GerencialBroker() {

    const [urlFilters, setUrlFilters] = useQueryStates({
        credor: parseAsString,
        tribunal: parseAsString,
        esfera: parseAsString,
        status: parseAsString,
        criado_por: parseAsString,
        coordenador: parseAsString,
        host: parseAsString,
    });

    const setIsCoordenadorOrMaster = useBrokerStore((store) => store.setIsCoordenadorOrMaster);
    const { userRole, userName, userHost } = useUserInfoStore(
        useShallow((s) => ({
            userRole: s.data.role,
            userName: s.data.user,
            userHost: s.data.host,
        })),
    );

    const isMobile = useIsMobile();

    const chartFilters = [
        { id: 'host', label: 'Host', value: urlFilters.host || userHost },
        { id: 'criado_por', label: 'Usuário', value: urlFilters.criado_por || userName },
        { id: 'coordenador', label: 'Coordenador', value: urlFilters.coordenador },
    ];

    const {
        data: chartsData,
        isLoading: isLoadingChartsData,
        isError: isErrorChartsData,
    } = useQuery(createBrokerDashboardChartsQueryOptions(chartFilters, userName, urlFilters.host || userHost || undefined));

    useEffect(() => {
        if (canAccessCoordinatorData(userRole)) {
            setIsCoordenadorOrMaster(true);
        } else {
            setIsCoordenadorOrMaster(false);
        }
    }, [userRole]);

    return (
        <div className="grid grid-cols-12">
            <div className="col-span-12 mb-5 grid h-fit grid-cols-1 items-center gap-5 lg:grid-cols-12">
                <BrokerQuantityDistribuitionChart
                    data={chartsData ?? []}
                    isLoading={isLoadingChartsData || !userName}
                    hasError={isErrorChartsData}
                />
                <BrokerComissionPreviewChart
                    data={chartsData ?? []}
                    isLoading={isLoadingChartsData || !userName}
                    hasError={isErrorChartsData}
                />
                <BrokerCommissionAcquiredChart
                    data={chartsData ?? []}
                    isLoading={isLoadingChartsData || !userName}
                    hasError={isErrorChartsData}
                />
            </div>


            {isMobile !== undefined ?
                <ProposalListWrapper
                    isFromGerencial
                    isMobile={isMobile}
                    urlFilters={urlFilters}
                    setUrlFilters={setUrlFilters}
                >
                    {isMobile ? <BrokerProposalList isFromGerencial /> : <BrokerPrecatoriosTable />}
                </ProposalListWrapper>
                : null}
        </div>
    );
}
export default GerencialBroker;

