import { DashboardBentoGrid } from './_components/grid/DashboardBentoGrid';
import './broker-bento-theme.css';
import { Metadata } from 'next';

export const metadata: Metadata = {
    title: 'CelerApp | CRM Dashboard',
    description: 'Dashboard do broker com visão em bento grid',
    category: 'CRM Dashboard',
    openGraph: {
        title: 'CelerApp | CRM Dashboard',
        description: 'Dashboard do broker com visão em bento grid',
    },
    applicationName: 'CelerApp',
};

export default function BrokerDashboardPage() {
    return (
        <div
            className="broker-bento-cockpit h-full min-h-0 flex-1 overflow-hidden"
            style={{
                paddingBlock: 'var(--bento-page-pad)',
                paddingInline: 'var(--bento-page-pad-x)',
            }}
        >
            <DashboardBentoGrid />
        </div>
    );
}
